import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int T = sc.nextInt();
        while (T-- > 0) {
            long N = sc.nextLong(), A = sc.nextLong(), B = sc.nextLong();
            boolean byA = N % A == 0;
            boolean byB = N % B == 0;
            if (byA && byB) System.out.println("N is divisible by A and B");
            else if (byA) System.out.println("N is divisible by only A");
            else if (byB) System.out.println("N is divisible by only B");
            else System.out.println("N is divisible by neither A nor B");
        }
    }
}

